# File: models.py import statistics from dataclasses import dataclass class ArticoloMagazzino:    """Rappresenta un articolo a domanda indipendente gestito a magazzino."""    def __init__(self, codice_sku: str, descrizione: str, costo_unitario: float,                 domanda_annua: float, costo_setup: float, costo_mantenimento: float,                 lead_time_medio: float, dev_std_lead_time: float = 0.0,                 dev_std_domanda: float = 0.0, giorni_anno: int = 365):        self.codice_sku = codice_sku.strip().upper()        self.descrizione = descrizione.strip()        self.costo_unitario = float(costo_unitario)        self.domanda_annua = float(domanda_annua)        self.costo_setup = float(costo_setup)        self.costo_mantenimento = float(costo_mantenimento)        self.lead_time_medio = float(lead_time_medio)        self.dev_std_lead_time = float(dev_std_lead_time)        self.giorni_anno = int(giorni_anno)        self.domanda_giornaliera = self.domanda_annua / self.giorni_anno        self.dev_std_domanda = float(dev_std_domanda)        self.valida_parametri()    def valida_parametri(self) -> None:        """Verifica la coerenza fisica e matematica dei parametri inseriti."""        if not self.codice_sku:            raise ValueError("Il codice SKU dell'articolo non può essere vuoto.")        if self.domanda_annua <= 0:            raise ValueError("La domanda annua (D) deve essere strettamente maggiore di zero.")        if self.costo_setup <= 0:            raise ValueError("Il costo di setup/ordinazione (S) deve essere maggiore di zero.")        if self.costo_mantenimento <= 0:            raise ValueError("Il costo annuo di mantenimento (H) deve essere maggiore di zero.")        if self.lead_time_medio < 0 or self.dev_std_lead_time < 0:            raise ValueError("Il lead time e la sua deviazione standard non possono essere negativi.")        if self.dev_std_domanda < 0:            raise ValueError("La deviazione standard della domanda non può essere negativa.")    def aggiorna_da_storico(self, serie_giornaliera: list[float]) -> None:        """Ricalcola D, d e sigma_d a partire dai dati storici triennali (1.095 giorni)."""        if len(serie_giornaliera) < 365:            raise ValueError("La serie storica deve contenere almeno 365 osservazioni giornaliere.")        media_g = statistics.mean(serie_giornaliera)        self.domanda_giornaliera = media_g        self.domanda_annua = media_g * self.giorni_anno        self.dev_std_domanda = statistics.stdev(serie_giornaliera)        self.valida_parametri()